def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    n=data[0]
    pairs=[(data[i],data[i+1]) for i in range(1,len(data),2)]
    byx=[0]*n
    for x,y in pairs: byx[x-1]=y
    compat=[]
    for k in range(n):
        m=0
        for j in range(n):
            if (j<k and byx[j]<byx[k]) or (j>k and byx[j]>byx[k]):
                m |= 1<<j
        compat.append(m)
    full=(1<<n)-1
    states={full}
    todo=[full]
    while todo:
        mask=todo.pop()
        for k in range(n):
            if mask>>k&1:
                nxt=mask & ~compat[k]
                if nxt not in states:
                    states.add(nxt); todo.append(nxt)
    print(len(states)%998244353)
