import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    arr = data[1:]

    # For each prime, record its exponent in every A_i.
    factors = {}
    m = len(arr)
    for i, value in enumerate(arr):
        x = value
        d = 2
        while d * d <= x:
            if x % d == 0:
                exponent = 0
                while x % d == 0:
                    x //= d
                    exponent += 1
                factors.setdefault(d, [0] * m)[i] = exponent
            d += 1
        if x > 1:
            factors.setdefault(x, [0] * m)[i] = 1

    answer = 1
    for prime, exponents in factors.items():
        bound = sum(exponents)
        prime_power = [1] * (bound + 1)
        for e in range(1, bound + 1):
            prime_power[e] = prime_power[e - 1] * prime % MOD

        # dp[h]: weighted sum for normalized walk heights ending at h.
        # The accumulated weight is the product of prime**height over
        # all vertices processed so far.
        dp = {0: 1}
        for i, step in enumerate(exponents):
            next_dp = {}
            old_vertices = i + 1
            if step == 0:
                for height, ways in dp.items():
                    next_dp[height] = (next_dp.get(height, 0) + ways * prime_power[height]) % MOD
            else:
                # If this move establishes a new minimum by delta, all
                # old vertex heights increase by delta.
                crossing_factor = [pow(prime, delta * old_vertices, MOD)
                                   for delta in range(step + 1)]
                for height, ways in dp.items():
                    # The walk moves up by step.
                    new_height = height + step
                    next_dp[new_height] = (next_dp.get(new_height, 0) + ways * prime_power[new_height]) % MOD

                    # Or it moves down by step.
                    if height >= step:
                        new_height = height - step
                        next_dp[new_height] = (next_dp.get(new_height, 0) + ways * prime_power[new_height]) % MOD
                    else:
                        delta = step - height
                        next_dp[0] = (next_dp.get(0, 0) + ways * crossing_factor[delta]) % MOD
            dp = next_dp

        answer = answer * (sum(dp.values()) % MOD) % MOD

    print(answer)

if __name__ == '__main__':
    main()

