from typing import List
import heapq
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        events=[[] for _ in range(n+1)]
        for i,(x,y) in enumerate(conflictingPairs):
            a,b=sorted((x,y))
            events[b].append((a,i))
        heap=[]
        gain=[0]*len(conflictingPairs)
        total=0
        for r in range(1,n+1):
            for a,i in events[r]:
                heapq.heappush(heap,(-a,i))
            first=heap[0] if heap else (0,-1)
            if heap:
                a1=-first[0]; i=first[1]
                heapq.heappop(heap)
                a2=-heap[0][0] if heap else 0
                heapq.heappush(heap,first)
                total += r-a1
                gain[i] += a1-a2
            else:
                total += r
        return total+max(gain)

