import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data: return
    it=iter(data)
    n=next(it); m=next(it); q=next(it)
    edges=[]
    for _ in range(m):
        edges.append((next(it)-1,next(it)-1,next(it)))
    queries=[]; closed=set()
    for _ in range(q):
        t=next(it)
        if t==1:
            e=next(it)-1; queries.append((1,e)); closed.add(e)
        else:
            queries.append((2,next(it)-1,next(it)-1))
    inf=10**30
    d=[[inf]*n for _ in range(n)]
    for i in range(n): d[i][i]=0
    for e,(a,b,c) in enumerate(edges):
        if e not in closed: d[a][b]=d[b][a]=c
    for k in range(n):
        dk=d[k]
        for i in range(n):
            dik=d[i][k]
            if dik==inf: continue
            di=d[i]
            for j in range(n):
                v=dik+dk[j]
                if v<di[j]: di[j]=v
    ans=[]
    for qu in reversed(queries):
        if qu[0]==2:
            v=d[qu[1]][qu[2]]
            ans.append(str(v if v<inf else -1))
        else:
            a,b,c=edges[qu[1]]
            da=[d[i][a] for i in range(n)]
            db=[d[i][b] for i in range(n)]
            for i in range(n):
                di=d[i]
                for j in range(i,n):
                    v=min(da[i]+c+db[j],db[i]+c+da[j])
                    if v<di[j]:
                        di[j]=v; d[j][i]=v
    sys.stdout.write('\n'.join(reversed(ans)))

if __name__=='__main__': main()

