size=4*n
tree=[0]*size
lazy=[0]*size
def build(node,l,r):
    if l==r:
        tree[node]=pref[l]
        return
    m=(l+r)//2
    build(node*2,l,m); build(node*2+1,m+1,r)
    tree[node]=max(tree[node*2],tree[node*2+1])
def apply(node,v):
    tree[node]+=v; lazy[node]+=v
def push(node):
    v=lazy[node]
    if v:
        apply(node*2,v); apply(node*2+1,v); lazy[node]=0
def add(node,l,r,ql,qr,v):
    if ql<=l and r<=qr:
        apply(node,v); return
    push(node); m=(l+r)//2
    if ql<=m: add(node*2,l,m,ql,qr,v)
    if qr>m: add(node*2+1,m+1,r,ql,qr,v)
    tree[node]=max(tree[node*2],tree[node*2+1])
