import sys
from math import gcd

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, budget = data[0], data[1]
    processes = []
    pos = 2
    for _ in range(n):
        a, p, b, q = data[pos:pos + 4]
        pos += 4
        g = gcd(a, b)
        processes.append((a, p, b, q, g))

    def feasible(target):
        total_cost = 0
        for a, p, b, q, g in processes:
            if target == 0:
                continue

            # Equal-output exchanges show that an optimum has either
            # fewer than b/g S machines or fewer than a/g T machines.
            if (a // g) * q - (b // g) * p < 0:
                best = 10**30
                for x in range(b // g):
                    y = max(0, (target - a * x + b - 1) // b)
                    best = min(best, x * p + y * q)
            else:
                best = 10**30
                for y in range(a // g):
                    x = max(0, (target - b * y + a - 1) // a)
                    best = min(best, y * q + x * p)

            total_cost += best
            if total_cost > budget:
                return False
        return True

    low, high = 0, 100 * budget + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

