class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Binomial coefficients modulo MOD.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for i in range(1, n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        # depth[x] is the number of popcount operations needed to reach 1 from x.
        depth = [0] * (n + 1)
        for x in range(2, n + 1):
            depth[x] = 1 + depth[x.bit_count()]

        # A number with popcount c needs one operation to become c,
        # followed by depth[c] operations to become 1.
        good = [False] * (n + 1)
        for c in range(1, n + 1):
            good[c] = 1 + depth[c] <= k

        ans = 0
        for target_ones in range(1, n + 1):
            if not good[target_ones]:
                continue
            prefix_ones = 0
            ways = 0
            for i, bit in enumerate(s):
                remaining = n - i - 1
                if bit == '1':
                    need = target_ones - prefix_ones
                    if 0 <= need <= remaining:
                        ways += comb[remaining][need]
                    prefix_ones += 1
            ans = (ans + ways) % MOD

        return ans

