import sys
from collections import deque

def main():
    input = sys.stdin.readline
    n = int(input())
    graph = [input().strip() for _ in range(n)]

    # For each vertex and letter, record incoming and outgoing neighbors.
    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]
    for u in range(n):
        for v, ch in enumerate(graph[u]):
            if ch != '-':
                c = ord(ch) - 97
                outgoing[u][c].append(v)
                incoming[v][c].append(u)

    dist = [[-1] * n for _ in range(n)]
    q = deque()

    for u in range(n):
        dist[u][u] = 0
        q.append((u, u))
    for u in range(n):
        for v, ch in enumerate(graph[u]):
            if ch != '-' and dist[u][v] == -1:
                dist[u][v] = 1
                q.append((u, v))

    while q:
        u, v = q.popleft()
        nd = dist[u][v] + 2
        for c in range(26):
            left = incoming[u][c]
            right = outgoing[v][c]
            for a in left:
                row = dist[a]
                for b in right:
                    if row[b] == -1:
                        row[b] = nd
                        q.append((a, b))

    print('\n'.join(' '.join(map(str, row)) for row in dist))

if __name__ == "__main__":
    main()

