import sys
MOD = 998244353
N = int(sys.stdin.readline())
S = sys.stdin.readline().strip()

# y = number of already-seen black vertices paired with a white vertex
# still to come. x = number of seen whites paired with a black still to come.
# At every internal cut y must be positive: this is precisely the condition
# that some added edge crosses that cut from right to left.
d = 0  # seen whites - seen blacks, so x-y=d
D = [0] * (N + 2)
D[0] = 1
for i, c in enumerate(S):
    nd = [0] * (N + 2)
    if c == 'B':
        # Pair B to an unmatched earlier W (x choices), or reserve it for a later W.
        for y, v in enumerate(D):
            if v:
                x = y + d
                if x > 0:
                    nd[y] = (nd[y] + v * x) % MOD
                if y + 1 <= N:
                    nd[y + 1] = (nd[y + 1] + v) % MOD
        d -= 1
    else:
        # Pair W to one of y reserved B's, or reserve W for a later B.
        for y, v in enumerate(D):
            if v:
                if y > 0:
                    nd[y - 1] = (nd[y - 1] + v * y) % MOD
                nd[y] = (nd[y] + v) % MOD
        d += 1
    if i + 1 < len(S):
        nd[0] = 0
    D = nd
print(D[0] % MOD)

