from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # For each prefix-index residue modulo k, retain the smallest
        # earlier prefix sum. Pairing it with the current prefix maximizes
        # the sum of a subarray whose length is divisible by k.
        min_prefix = [None] * k
        min_prefix[0] = 0
        prefix = 0
        answer = None

        for j, value in enumerate(nums, 1):
            prefix += value
            residue = j % k

            if min_prefix[residue] is not None:
                candidate = prefix - min_prefix[residue]
                if answer is None or candidate > answer:
                    answer = candidate

            if min_prefix[residue] is None or prefix < min_prefix[residue]:
                min_prefix[residue] = prefix

        return answer

