from math import gcd

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        def score(values: List[int]) -> int:
            if not values:
                return 0
            common = values[0]
            multiple = values[0]
            for value in values[1:]:
                common = gcd(common, value)
                multiple = multiple // gcd(multiple, value) * value
            return common * multiple

        best = score(nums)
        for i in range(len(nums)):
            best = max(best, score(nums[:i] + nums[i + 1:]))
        return best

