class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        counts = {}
        for value in nums:
            counts[value] = counts.get(value, 0) + 1

        for outlier in sorted(nums, reverse=True):
            remainder = total - outlier
            if remainder % 2 == 0:
                sum_value = remainder // 2
                available = counts.get(sum_value, 0)
                if sum_value == outlier:
                    available -= 1  # Reserve a distinct index for the outlier.
                if available > 0:
                    return outlier
        return 0  # The input guarantees a potential outlier exists.

