class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        m = len(queries)

        def feasible(k: int) -> bool:
            for i, target in enumerate(nums):
                if target == 0:
                    continue
                # Bit s is set iff a subset of applicable query values sums to s.
                possible = 1
                limit = (1 << (target + 1)) - 1
                for l, r, val in queries[:k]:
                    if l <= i <= r:
                        possible |= possible << val
                        possible &= limit
                if not (possible >> target) & 1:
                    return False
            return True

        if not feasible(m):
            return -1

        lo, hi = 0, m
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

