import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        limit = 10000
        is_prime = [True] * limit
        is_prime[0] = is_prime[1] = False
        for p in range(2, 100):
            if is_prime[p]:
                for x in range(p * p, limit, p):
                    is_prime[x] = False

        if is_prime[n] or is_prime[m]:
            return -1

        # Dijkstra: entering a value x adds x to the total transformation cost.
        dist = {n: n}
        heap = [(n, n)]
        while heap:
            cost, x = heapq.heappop(heap)
            if dist.get(x) != cost:
                continue
            if x == m:
                return cost

            digits = list(str(x))
            for i, ch in enumerate(digits):
                digit = int(ch)
                for changed in (digit - 1, digit + 1):
                    if 0 <= changed <= 9:
                        nxt_digits = digits.copy()
                        nxt_digits[i] = str(changed)
                        nxt = int(''.join(nxt_digits))
                        if is_prime[nxt]:
                            continue
                        new_cost = cost + nxt
                        if new_cost < dist.get(nxt, float('inf')):
                            dist[nxt] = new_cost
                            heapq.heappush(heap, (new_cost, nxt))
        return -1

