class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        def z_values(a):
            m = len(a)
            z = [0] * m
            left = right = 0
            for k in range(1, m):
                if k < right:
                    z[k] = min(right - k, z[k - left])
                while k + z[k] < m and a[z[k]] == a[k + z[k]]:
                    z[k] += 1
                if k + z[k] > right:
                    left, right = k, k + z[k]
            return z

        whole_z = z_values(nums)
        answer = 0
        for i in range(1, n - 1):
            if whole_z[i] >= i:
                # Every possible second cut satisfies nums1 is a prefix of nums2.
                answer += n - i - 1
                continue

            # Otherwise, test whether nums[i:j] is a prefix of nums[j:].
            z = z_values(nums[i:])
            for d in range(1, n - i):
                if z[d] >= d:
                    answer += 1
        return answer

