import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]
    best = [None, None]  # best sequence ending at an even/odd index

    for i, x in enumerate(a, 1):
        parity = i & 1
        previous = best[1 - parity]
        if parity:  # An odd index can start the final stack.
            value = x if previous is None else x + max(0, previous)
        else:
            if previous is None:
                continue
            value = x + previous
        if best[parity] is None or value > best[parity]:
            best[parity] = value

    answer = best[n & 1]
    if n % 2 == 0:
        answer = max(0, answer if answer is not None else 0)
    print(answer)

