    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # A state assigns colors to a mirrored pair: left and right.
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        m = n // 2
        dp = [cost[0][a] + cost[n - 1][b] for a, b in states]

        # Add mirrored pairs moving inward. Consecutive pairs must differ
        # on both the left and right sides.
        for i in range(1, m):
            ndp = [10**30] * len(states)
            for s, (a, b) in enumerate(states):
                pair_cost = cost[i][a] + cost[n - 1 - i][b]
                for t, (x, y) in enumerate(states):
                    if a != x and b != y:
                        ndp[s] = min(ndp[s], dp[t] + pair_cost)
            dp = ndp

        return min(dp)

