    def countOfSubstrings(self, word: str, k: int) -> int:
        vowel_bit = {'a': 1, 'e': 2, 'i': 4, 'o': 8, 'u': 16}
        n = len(word)
        total = 0

        for left in range(n):
            mask = 0
            consonants = 0
            for right in range(left, n):
                ch = word[right]
                if ch in vowel_bit:
                    mask |= vowel_bit[ch]
                else:
                    consonants += 1

                # Further extensions cannot reduce the consonant count.
                if consonants > k:
                    break
                if consonants == k and mask == 31:
                    total += 1

        return total

